$ErrorActionPreference="Stop";Set-StrictMode -Version Latest
$R=$PSScriptRoot;$E=Split-Path -Parent $R;$T=Split-Path -Parent $E;$Repo=Split-Path -Parent $T;$P=Join-Path $T "WildsEngine.Core.Tests.csproj";$Reports=Join-Path $E "Reports";$Stamp=Get-Date -Format "yyyyMMdd-HHmmss";$Report=Join-Path $Reports "E7-H4A-Certification-$Stamp.txt";$Latest=Join-Path $Reports "E7-H4A-Certification-Latest.txt";New-Item -ItemType Directory -Path $Reports -Force|Out-Null
function W([string]$x=""){Write-Host $x;$x|Out-File $Report -Append -Encoding utf8};function Run([string]$n,[scriptblock]$c){W "";W $n;&$c 2>&1|%{W ([string]$_)};if($LASTEXITCODE -ne 0){throw "$n failed."}}
if(@(git -C $Repo status --short -- .\WildsEngine.Core).Count -gt 0){throw "Core has changes."};W "WILDS DISCOVERIES E7-H4A CERTIFICATION";W "Core guard: PASS";Run "RELEASE BUILD" {dotnet build $P -c Release};Run "H4A ASSERTIONS" {dotnet test $P -c Release --no-build --filter "FullyQualifiedName~DiscoveryRecognizedGeometryPopulationCertificationTests"};Run "H4A READABLE" {dotnet test $P -c Release --no-build --filter "FullyQualifiedName~DiscoveryRecognizedGeometryPopulationReadableTests" --logger "console;verbosity=detailed"};if(@(git -C $Repo status --short -- .\WildsEngine.Core).Count -gt 0){throw "Core changed."};W "RESULT: PASS";W "Core unchanged. H4A immutable scoped recognized-geometry population certified without averaging distinct structures.";Copy-Item $Report $Latest -Force;Write-Host "Latest: $Latest"
